// Exponential Backoff with Full Jitter (The AWS standard formula):
function getRetryDelay(attempt, baseDelay = 100, maxDelay = 10000) {
  const expDelay = Math.min(maxDelay, baseDelay * (2 ** attempt));
  // Full Jitter: randomize between 0 and expDelay
  return Math.random() * expDelay;
}
